<?php use yii\helpers\Html;use yii\widgets\ActiveForm;$this->title='Transactions';?><div class="toolbar"><p>Record receiving, issuance, transfer, return, repair, disposal, and adjustments.</p><button class="btn primary" onclick="document.getElementById('trx').hidden=false">+ New transaction</button></div><section id="trx" class="panel formpanel" hidden><?php $f=ActiveForm::begin(['options'=>['class'=>'gridform']]);?><?php foreach(['date','type','property_number','description','from_office','to_office','to_person','quantity','reference_no','status','remarks'] as $k)echo $f->field($model,$k);?><?=Html::submitButton('Record transaction',['class'=>'btn primary'])?><?php ActiveForm::end();?></section><section class="panel tablepanel"><div class="scroll"><table><thead><tr><th>ID</th><th>Date</th><th>Type</th><th>Property No.</th><th>Description</th><th>From</th><th>To</th><th>Qty</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach(['transaction_id','date','type','property_number','description','from_office','to_office','quantity','status'] as $k):?><td><?=Html::encode($r->$k)?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div></section>
